BEGIN;
CREATE TABLE knowledge_evidence(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,evidence_id uuid NOT NULL,source_id uuid NOT NULL,asset_id uuid NOT NULL,version_id uuid NOT NULL,classification text NOT NULL,locator_kind text NOT NULL CHECK(locator_kind IN('page','section','record','offset')),locator_value text NOT NULL CHECK(char_length(locator_value)<=256),start_offset integer NOT NULL CHECK(start_offset>=0),end_offset integer NOT NULL CHECK(end_offset>start_offset),original_checksum text NOT NULL CHECK(original_checksum~'^sha256:[a-f0-9]{64}$'),normalized_checksum text NOT NULL CHECK(normalized_checksum~'^sha256:[a-f0-9]{64}$'),excerpt_hash text NOT NULL CHECK(excerpt_hash~'^sha256:[a-f0-9]{64}$'),valid_from timestamptz NOT NULL,valid_until timestamptz,status text NOT NULL CHECK(status IN('valid','invalid')),invalidated_at timestamptz,invalidation_reason text,PRIMARY KEY(tenant_id,workspace_id,evidence_id),FOREIGN KEY(tenant_id,workspace_id,asset_id,version_id)REFERENCES knowledge_version_governance(tenant_id,workspace_id,asset_id,version_id)ON DELETE RESTRICT,CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE TABLE knowledge_entity(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,entity_id uuid NOT NULL,taxonomy_id uuid NOT NULL,taxonomy_version_id uuid NOT NULL,entity_type text NOT NULL,canonical_hash text NOT NULL CHECK(canonical_hash~'^sha256:[a-f0-9]{64}$'),aliases jsonb NOT NULL CHECK(jsonb_typeof(aliases)='array'AND jsonb_array_length(aliases)<=50),owner_id uuid NOT NULL,state text NOT NULL CHECK(state IN('candidate','confirmed','merged','retired')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),PRIMARY KEY(tenant_id,workspace_id,entity_id),FOREIGN KEY(tenant_id,workspace_id,taxonomy_id,taxonomy_version_id)REFERENCES knowledge_taxonomy_version(tenant_id,workspace_id,taxonomy_id,version_id)ON DELETE RESTRICT,UNIQUE(tenant_id,workspace_id,entity_type,canonical_hash));
CREATE TABLE knowledge_claim(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,claim_id uuid NOT NULL,owner_id uuid NOT NULL,author_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('fact','inference','rule_candidate')),canonical_hash text NOT NULL CHECK(canonical_hash~'^sha256:[a-f0-9]{64}$'),statement_hash text NOT NULL CHECK(statement_hash~'^sha256:[a-f0-9]{64}$'),statement_ref text NOT NULL CHECK(statement_ref~'^artifactref:'),confidence numeric(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1),classification text NOT NULL,valid_from timestamptz NOT NULL,valid_until timestamptz,state text NOT NULL CHECK(state IN('candidate','in_review','published','conflicted','rejected','revoked')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),reviewed_by uuid,reason_hash text CHECK(reason_hash~'^sha256:[a-f0-9]{64}$'),PRIMARY KEY(tenant_id,workspace_id,claim_id),UNIQUE(tenant_id,workspace_id,canonical_hash,valid_from),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE TABLE knowledge_claim_evidence(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,claim_id uuid NOT NULL,evidence_id uuid NOT NULL,position integer NOT NULL CHECK(position BETWEEN 0 AND 49),PRIMARY KEY(tenant_id,workspace_id,claim_id,evidence_id),FOREIGN KEY(tenant_id,workspace_id,claim_id)REFERENCES knowledge_claim(tenant_id,workspace_id,claim_id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,workspace_id,evidence_id)REFERENCES knowledge_evidence(tenant_id,workspace_id,evidence_id)ON DELETE RESTRICT,UNIQUE(tenant_id,workspace_id,claim_id,position));
CREATE TABLE knowledge_relation(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,relation_id uuid NOT NULL,subject_entity_id uuid NOT NULL,predicate text NOT NULL,object_entity_id uuid NOT NULL,confidence numeric(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1),state text NOT NULL CHECK(state IN('candidate','confirmed','rejected','revoked')),version bigint NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,workspace_id,relation_id),FOREIGN KEY(tenant_id,workspace_id,subject_entity_id)REFERENCES knowledge_entity(tenant_id,workspace_id,entity_id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,workspace_id,object_entity_id)REFERENCES knowledge_entity(tenant_id,workspace_id,entity_id)ON DELETE RESTRICT,CHECK(subject_entity_id<>object_entity_id));
CREATE TABLE knowledge_graph_outbox(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,event_id uuid NOT NULL,event_type text NOT NULL CHECK(event_type IN('knowledge.claim.candidate.v1','knowledge.claim.published.v1','knowledge.claim.conflicted.v1','knowledge.claim.revoked.v1','knowledge.evidence.invalidated.v1','knowledge.entity.confirmed.v1','knowledge.relation.confirmed.v1')),request_id uuid NOT NULL,subject_id uuid NOT NULL,subject_hash text NOT NULL,state text NOT NULL,subject_version bigint NOT NULL,occurred_at timestamptz NOT NULL,published_at timestamptz,PRIMARY KEY(tenant_id,workspace_id,event_id));
REVOKE ALL ON knowledge_evidence,knowledge_entity,knowledge_claim,knowledge_claim_evidence,knowledge_relation,knowledge_graph_outbox FROM PUBLIC;GRANT SELECT,INSERT,UPDATE(status,invalidated_at,invalidation_reason)ON knowledge_evidence TO domus_knowledge_runtime;GRANT SELECT,INSERT,UPDATE(state,version)ON knowledge_entity,knowledge_relation TO domus_knowledge_runtime;GRANT SELECT,INSERT,UPDATE(state,version,reviewed_by,reason_hash)ON knowledge_claim TO domus_knowledge_runtime;GRANT SELECT,INSERT ON knowledge_claim_evidence,knowledge_graph_outbox TO domus_knowledge_runtime;
ALTER TABLE knowledge_evidence ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_evidence FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_entity ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_entity FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_claim ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_claim FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_claim_evidence ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_claim_evidence FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_relation ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_relation FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_graph_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_graph_outbox FORCE ROW LEVEL SECURITY;
CREATE POLICY evidence_scope ON knowledge_evidence TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY entity_scope ON knowledge_entity TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY claim_scope ON knowledge_claim TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY claim_evidence_scope ON knowledge_claim_evidence TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY relation_scope ON knowledge_relation TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY graph_outbox_scope ON knowledge_graph_outbox TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));
INSERT INTO schema_migrations(version,description)VALUES(18,'V1-408 evidence bound claims and graph lite')ON CONFLICT(version)DO NOTHING;COMMIT;
